SELECT  FROM ops_alert_event
WHERE rule_id = #{ruleId}
  AND condition_type = #{conditionType}
  AND target_id IS NOT DISTINCT FROM #{targetId}
ORDER BY observed_at DESC, id DESC
LIMIT 1

SELECT  FROM ops_alert_event

    AND rule_id = #{ruleId}
    AND target_id = #{targetId}
    AND state = #{state}

ORDER BY observed_at DESC, id DESC
LIMIT #{limit}
